package com.gk.jobhelper.controller;
import com.gk.jobhelper.common.ApiResponse;import com.gk.jobhelper.dto.*;import com.gk.jobhelper.service.*;import java.util.List;import javax.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/recruitment") public class RecruitmentController {private final RecruitmentDiscoveryService discovery;private final RecruitmentNoticeService notices;private final RecruitmentDetailService details;private final RecruitmentPositionService positions;private final RecruitmentNoticeImageService images;public RecruitmentController(RecruitmentDiscoveryService d,RecruitmentNoticeService n,RecruitmentDetailService s,RecruitmentPositionService p,RecruitmentNoticeImageService i){discovery=d;notices=n;details=s;positions=p;images=i;}@PostMapping("/discovery")public ApiResponse<RecruitmentDiscoveryResult> discovery(){return ApiResponse.ok(discovery.discoverAll());}@GetMapping("/notices")public ApiResponse<PageVO<RecruitmentNoticeVO>> page(@RequestParam(required=false)String status,@RequestParam(required=false)String sourceCode,@RequestParam(required=false)String keyword,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize){return ApiResponse.ok(notices.page(status,sourceCode,keyword,page,pageSize));}@GetMapping("/notices/{id}")public ApiResponse<RecruitmentNoticeVO> detail(@PathVariable Long id){return ApiResponse.ok(notices.detail(id));}@PostMapping("/notices/{id}/fetch-detail")public ApiResponse<RecruitmentDetailFetchResponse> fetchDetail(@PathVariable Long id){return ApiResponse.ok(details.fetch(id));}@PostMapping("/notices/{id}/extract-positions")public ApiResponse<RecruitmentPositionExtractionResponse> extract(@PathVariable Long id){return ApiResponse.ok(positions.extract(id));}@PostMapping("/notices/{id}/extract-body-positions")public ApiResponse<RecruitmentPositionExtractionResponse> extractBody(@PathVariable Long id){return ApiResponse.ok(positions.extractBody(id));}@GetMapping("/notices/{id}/image")public ResponseEntity<byte[]> image(@PathVariable Long id,@RequestParam String url){RecruitmentNoticeImageService.Image image=images.load(id,url);return ResponseEntity.ok().contentType(MediaType.parseMediaType(image.type)).body(image.bytes);}@GetMapping("/notices/{id}/positions")public ApiResponse<List<RecruitmentPositionVO>> positions(@PathVariable Long id){return ApiResponse.ok(positions.list(id));}@GetMapping("/positions/{id}")public ApiResponse<RecruitmentPositionVO> position(@PathVariable Long id){return ApiResponse.ok(positions.detail(id));}@PutMapping("/notices/{id}/status")public ApiResponse<Void> status(@PathVariable Long id,@Valid @RequestBody RecruitmentNoticeStatusRequest request){notices.updateStatus(id,request.getStatus());return ApiResponse.ok();}@PostMapping("/notices/{id}/view")public ApiResponse<Void> view(@PathVariable Long id){notices.view(id);return ApiResponse.ok();}}
